1	package numeric
2	
3	import (
4		"encoding/base64"
5		"encoding/json"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sort"
10		"strings"
11		"sync/atomic"
12		"time"
13		"unicode/utf8"
14	)
15	
16	// rawBase64Prefix 标记 _raw 字段中的值是原始字节的 base64 编码。
17	// ':' 不在 base64 字母表内，普通文本（即使本身像 base64，如 "abcd"）
18	// 不会以该前缀开头；而 _raw 字段由本版本写入，旧归档不含此字段，
19	// 因此标记无歧义。
20	const rawBase64Prefix = "base64:"
21	
22	// unmarshalRaw 恢复 rawIdentity 写出的字段；带 base64 前缀的兜底值解码回
23	// 原始字节，普通 JSON 字符串原样返回。
24	func unmarshalRaw(s string) (string, error) {
25		if strings.HasPrefix(s, rawBase64Prefix) {
26			b, err := base64.StdEncoding.DecodeString(s[len(rawBase64Prefix):])
27			if err != nil {
28				return "", fmt.Errorf("numeric: 标识原始字节解码失败: %w", err)
29			}
30			return string(b), nil
31		}
32		return s, nil
33	}
34	
35	// identityRaw 携带提交人、请求号的完整字节兜底表示。只有当对应字段含
36	// 非法 UTF-8 字节时相应成员才非空；普通文本记录不写这两个字段，
37	// 保持旧格式归档可直接打开。
38	type identityRaw struct {
39		Submitter string `json:"submitter_raw,omitempty"`
40		RequestID string `json:"request_id_raw,omitempty"`
41	}
42	
43	// rawIdentity 在标识含非法 UTF-8 字节时构造完整字节兜底字段；
44	// 两个标识都是合法 UTF-8 时返回 nil，记录与旧格式完全一致。
45	func rawIdentity(submitter, requestID string) *identityRaw {
46		if utf8.ValidString(submitter) && utf8.ValidString(requestID) {
47			return nil
48		}
49		raw := &identityRaw{}
50		if !utf8.ValidString(submitter) {
51			raw.Submitter = rawBase64Prefix + base64.StdEncoding.EncodeToString([]byte(submitter))
52		}
53		if !utf8.ValidString(requestID) {
54			raw.RequestID = rawBase64Prefix + base64.StdEncoding.EncodeToString([]byte(requestID))
55		}
56		return raw
57	}
58	
59	// resolveIdentity 恢复提交人、请求号：_raw 兜底字段存在且非空时以其
60	// 解码出的完整字节为准，否则使用 JSON 字符串字段（旧归档与普通文本）。
61	func resolveIdentity(plainSub, plainReq string, raw *identityRaw) (string, string, error) {
62		var err error
63		sub, req := plainSub, plainReq
64		if raw != nil {
65			if raw.Submitter != "" {
66				if sub, err = unmarshalRaw(raw.Submitter); err != nil {
67					return "", "", err
68				}
69			}
70			if raw.RequestID != "" {
71				if req, err = unmarshalRaw(raw.RequestID); err != nil {
72					return "", "", err
73				}
74			}
75		}
76		return sub, req, nil
77	}
78	
79	// recordVersion 是落盘记录格式的版本标记。
80	const recordVersion = "numeric-job-v1"
81	
82	// storedJob 是作业在内存中的完整状态，所有字段均由 Store.mu 保护。
83	type storedJob struct {
84		id           uint64
85		submitter    string
86		requestID    string
87		seed         int64
88		values       []int64
89		dependencies []uint64 // 有序直接上游作业号；空表示无依赖
90	
91		queuedAt   time.Time
92		startedAt  time.Time
93		finishedAt time.Time
94	
95		status        Status
96		failureReason string
97		blockerID     uint64
98	
99		// 成功后保存的有效输入与归档（与 succeeded 状态同一次原子写入）。
100		effectiveValues []int64
101		archive         *Archive
102	
103		// canceled 仅存于内存：运行中的作业收到取消/关闭请求后置位，
104		// 计算循环据此尽快中止；终态不会依赖它落盘（终态本身会持久化）。
105		canceled atomic.Bool
106	}
107	
108	// jobRecord 是 storedJob 的落盘 JSON 表示。成功状态与归档在同一记录内，
109	// 一次 temp-file + rename 原子写入，因此对外不会出现“成功却没有结果”。
110	type jobRecord struct {
111		Version string `json:"version"`
112	
113		ID        uint64 `json:"id"`
114		Submitter string `json:"submitter"`
115		RequestID string `json:"request_id"`
116		// IdentityRaw 仅在提交人或请求号含非法 UTF-8 字节时出现，按完整字节
117		// 保真恢复标识；合法 UTF-8（含 U+0000）时缺省，记录与旧格式一致。
118		IdentityRaw   *identityRaw `json:"identity_raw,omitempty"`
119		Seed          int64        `json:"seed"`
120		Values        []int64      `json:"values"`
121		HasDependency bool         `json:"has_dependency"`
122		DependencyID  uint64       `json:"dependency_id"`
123		// Dependencies 为有序直接上游作业号；旧格式记录无此字段，
124		// 恢复时由 HasDependency/DependencyID 推导。
125		Dependencies []uint64 `json:"dependencies,omitempty"`
126	
127		QueuedAt   time.Time `json:"queued_at"`
128		StartedAt  time.Time `json:"started_at,omitempty"`
129		FinishedAt time.Time `json:"finished_at,omitempty"`
130	
131		Status        Status `json:"status"`
132		FailureReason string `json:"failure_reason,omitempty"`
133		BlockerID     uint64 `json:"blocker_id,omitempty"`
134	
135		EffectiveValues []int64  `json:"effective_values,omitempty"`
136		Archive         *Archive `json:"archive,omitempty"`
137	}
138	
139	func jobFileName(id uint64) string {
140		return fmt.Sprintf("job-%020d.json", id)
141	}
142	
143	func (s *Store) jobPath(j *storedJob) string {
144		return filepath.Join(s.dir, jobFileName(j.id))
145	}
146	
147	func encodeRecord(j *storedJob) ([]byte, error) {
148		hasDependency, dependencyID := legacyDependencyFields(j.dependencies)
149		r := jobRecord{
150			Version: recordVersion,
151	
152			ID:            j.id,
153			Submitter:     j.submitter,
154			RequestID:     j.requestID,
155			IdentityRaw:   rawIdentity(j.submitter, j.requestID),
156			Seed:          j.seed,
157			Values:        append([]int64(nil), j.values...),
158			HasDependency: hasDependency,
159			DependencyID:  dependencyID,
160			Dependencies:  append([]uint64(nil), j.dependencies...),
161	
162			QueuedAt:      j.queuedAt,
163			StartedAt:     j.startedAt,
164			FinishedAt:    j.finishedAt,
165			Status:        j.status,
166			FailureReason: j.failureReason,
167			BlockerID:     j.blockerID,
168	
169			EffectiveValues: append([]int64(nil), j.effectiveValues...),
170			Archive:         j.archive,
171		}
172		return json.MarshalIndent(&r, "", "  ")
173	}
174	
175	// persist 在已持锁的情况下原子写一条作业记录。
176	func (s *Store) persist(j *storedJob) error {
177		// 测试用故障注入点（生产代码中 persistFault 恒为 nil）。
178		if s.persistFault != nil {
179			if err := s.persistFault(j); err != nil {
180				return err
181			}
182		}
183		data, err := encodeRecord(j)
184		if err != nil {
185			return err
186		}
187		return writeFileAtomic(s.dir, jobFileName(j.id), data, 0o600)
188	}
189	
190	// writeFileAtomic 将 data 写入 dir/name：同目录临时文件 → fsync → rename
191	// → 目录 fsync，保证记录要么是旧内容要么是新内容，不会出现半条记录。
192	func writeFileAtomic(dir, name string, data []byte, perm os.FileMode) error {
193		tmp, err := os.CreateTemp(dir, ".tmp-"+name+".*")
194		if err != nil {
195			return err
196		}
197		tmpName := tmp.Name()
198		cleanup := true
199		defer func() {
200			if cleanup {
201				_ = os.Remove(tmpName)
202			}
203		}()
204	
205		if _, err := tmp.Write(data); err != nil {
206			_ = tmp.Close()
207			return err
208		}
209		if err := tmp.Sync(); err != nil {
210			_ = tmp.Close()
211			return err
212		}
213		if err := tmp.Close(); err != nil {
214			return err
215		}
216		if err := os.Chmod(tmpName, perm); err != nil {
217			return err
218		}
219		if err := os.Rename(tmpName, filepath.Join(dir, name)); err != nil {
220			return err
221		}
222		cleanup = false
223		syncDir(dir)
224		return nil
225	}
226	
227	// syncDir 对目录本身做一次 fsync，让新建项与 rename 在崩溃后仍然成立。
228	func syncDir(dir string) {
229		if d, err := os.Open(dir); err == nil {
230			_ = d.Sync()
231			_ = d.Close()
232		}
233	}
234	
235	// loadDir 扫描目录中的全部作业记录并重建内存索引。
236	//
237	// 恢复规则：
238	//   - 上次关闭时仍为 running 的作业标记为失败，原因是计算被中断；
239	//   - 成功记录缺少归档、校验值对不上，依赖列表重复引用同一直接上游作业号，
240	//     或直接上游作业号不小于本作业号（引用自己或后来作业，违反提交时的
241	//     先后关系规则），实际输入与原始参数或直接依赖数量不对应，或归档数值
242	//     结果与有效输入按计算规则应得的结果不符时，fail-closed 地标记为失败，
243	//     维持“成功必有完整归档”的不变量；
244	//   - 有依赖的成功记录还要求每个直接上游都存在、恢复后仍是带完整归档的
245	//     成功状态，且实际输入的追加部分逐项等于这些上游按保存的依赖顺序
246	//     排列的总和；上游不可用的同样改判为失败，其失败原因指出直接上游、
247	//     BlockerID 沿链条保留最初的根因（与运行中依赖失败同一规则）；
248	//     仅追加输入对不上而上游全部有效的属于本作业自身归档有误，BlockerID
249	//     保持 0。排队记录的依赖列表重复引用同一作业号，或引用作业号不小于
250	//     自己的作业（自己/后来作业），同样在恢复时直接判失败（BlockerID 为
251	//     0），不再等待或开始计算；仍在排队的其他作业在同一趟升序扫描中按
252	//     既有依赖规则级联失败。
253	func loadDir(dir string) ([]*storedJob, uint64, error) {
254		entries, err := os.ReadDir(dir)
255		if err != nil {
256			return nil, 0, err
257		}
258		var jobs []*storedJob
259		var maxID uint64
260		for _, e := range entries {
261			name := e.Name()
262			if e.IsDir() {
263				continue
264			}
265			// 清理上一进程崩溃时可能残留的原子写临时文件。
266			if strings.HasPrefix(name, ".tmp-") {
267				_ = os.Remove(filepath.Join(dir, name))
268				continue
269			}
270			if !strings.HasPrefix(name, "job-") || !strings.HasSuffix(name, ".json") {
271				continue
272			}
273			path := filepath.Join(dir, name)
274			data, err := os.ReadFile(path)
275			if err != nil {
276				return nil, 0, err
277			}
278			var r jobRecord
279			if err := json.Unmarshal(data, &r); err != nil {
280				return nil, 0, fmt.Errorf("numeric: 记录 %s 损坏: %w", name, err)
281			}
282			if r.Version != recordVersion {
283				return nil, 0, fmt.Errorf("numeric: 记录 %s 版本不受支持: %s", name, r.Version)
284			}
285			// 提交人、请求号按完整字节恢复：含非法 UTF-8 字节时以
286			// identity_raw 兜底字段为准，普通文本（含 U+0000）与旧归档原样使用。
287			submitter, requestID, err := resolveIdentity(r.Submitter, r.RequestID, r.IdentityRaw)
288			if err != nil {
289				return nil, 0, fmt.Errorf("numeric: 记录 %s 标识损坏: %w", name, err)
290			}
291			// 成功归档内嵌同一份标识，同样按其自身兜底字段恢复，保证顶层记录
292			// 与归档中的参数逐字节一致。
293			if r.Archive != nil {
294				aSub, aReq, aErr := resolveIdentity(r.Archive.Submitter, r.Archive.RequestID, r.Archive.IdentityRaw)
295				if aErr != nil {
296					return nil, 0, fmt.Errorf("numeric: 记录 %s 归档标识损坏: %w", name, aErr)
297				}
298				r.Archive.Submitter = aSub
299				r.Archive.RequestID = aReq
300			}
301			switch r.Status {
302			case StatusQueued, StatusRunning, StatusSucceeded, StatusFailed, StatusCanceled:
303			default:
304				return nil, 0, fmt.Errorf("numeric: 记录 %s 状态非法: %q", name, r.Status)
305			}
306			// 新格式记录直接给出有序依赖列表；旧格式记录只有单依赖字段，
307			// 恢复为只含一个作业号的列表（语义与提交时一致）。两类字段同时
308			// 出现时以非空列表为实际依赖，与提交、归档核对共用同一换算。
309			deps := normalizeDependencies(r.HasDependency, r.DependencyID, r.Dependencies)
310			j := &storedJob{
311				id:           r.ID,
312				submitter:    submitter,
313				requestID:    requestID,
314				seed:         r.Seed,
315				values:       append([]int64(nil), r.Values...),
316				dependencies: deps,
317	
318				queuedAt:   r.QueuedAt,
319				startedAt:  r.StartedAt,
320				finishedAt: r.FinishedAt,
321	
322				status:        r.Status,
323				failureReason: r.FailureReason,
324				blockerID:     r.BlockerID,
325	
326				effectiveValues: append([]int64(nil), r.EffectiveValues...),
327				archive:         r.Archive,
328			}
329			if j.status == StatusRunning {
330				failRestoredJob(dir, j, "计算被中断：归档上次关闭时作业仍在运行", 0)
331			}
332			if j.status == StatusSucceeded {
333				// 除完整性外，还必须满足三条独立的对应/复算规则：
334				//  0. 依赖列表自身合法，按以下顺序检查：
335				//     a. 同一直接上游作业号不能出现两次（相邻或隔着其他上游都算）。
336				//        这与提交时 validateDependencyShapeLocked 的唯一性要求一致；
337				//        旧版本或被改动的记录可能保存了重复引用，此时即使追加值、
338				//        总和、平方和、摘要、日志与校验值全部自洽，也不能当作合法
339				//        成功归档（重复引用会把同一上游总和追加两次）。
340				//     b. 每个直接上游作业号都必须严格小于本作业号。正常提交只能引用
341				//        已经存在的作业，作业号又按接受先后递增，所以引用自己或引用
342				//        后来作业都不可能通过提交校验；旧版本或被改动的记录可能保存
343				//        这种依赖，即使被引用作业确实存在且成功、本作业的追加值、总和、
344				//        平方和、摘要、日志与校验值全部自洽，也不能接受。已因重复
345				//        依赖判失败的记录保留重复失败说明，不再改写。
346				//     两项都属于本作业记录自身有误，在任何上游可用性核对之前判定，
347				//     BlockerID 为 0，不把被引用的有效上游判成失败。
348				//  1. 实际输入与原始参数、直接依赖数量逐项对应——原始序列非空且
349				//     按原次序完整出现在实际输入开头，总长度恰为原始长度加上直接
350				//     依赖数；摘要、日志、校验值只与“实际输入”绑定，换成另一份
351				//     序列（如 [-3,2] 冒充 [2,-3]）仍能全套自洽，只有按位置比对
352				//     原始参数与依赖数量才能识别。
353				//  2. 归档中的数值结果必须与实际输入按既有计算规则应得的结果一致：
354				//     日志、摘要与校验值都可能与错误数字自洽，只有按保存的实际
355				//     输入复算才能识别。
356				// 任一不符合都按损坏归档处理。第四条规则——追加部分逐项等于各
357				// 直接上游恢复后的总和——需要全部记录恢复完毕才能核对，
358				// 在排序后的第二趟扫描中执行。
359				var invalidReason string
360				if dupID, dup := duplicateDependency(j); dup {
361					invalidReason = duplicateDependencyReason(dupID)
362				} else if badID, bad := firstIllegalOrderingDependency(j); bad {
363					invalidReason = illegalOrderingDependencyReason(badID, j.id)
364				} else if !archiveIntact(j) {
365					invalidReason = "归档不完整或校验值不一致，成功结果不可用"
366				} else if !effectiveInputsCorrespond(j) {
367					invalidReason = "实际输入与原始参数或依赖数量不符，成功结果不可用"
368				} else if !archiveResultsValid(j) {
369					invalidReason = "归档数值结果与有效输入按计算规则应得的结果不符，成功结果不可用"
370				}
371				if invalidReason != "" {
372					// 归档自身校验不通过：属于本作业自身失败，不携带阻断根因。
373					failRestoredJob(dir, j, invalidReason, 0)
374				}
375			}
376			jobs = append(jobs, j)
377			if j.id > maxID {
378				maxID = j.id
379			}
380		}
381		// 恢复后的排列必须与关闭前的接受先后一致：作业号在接受时单调分配，
382		// 按作业号升序即提交先后。记录上的提交时间只用于时间范围过滤，
383		// 不参与排序——本机时钟回拨会让后接受的作业带有更早的时间，
384		// 按时间重排会改变已确定的先后关系（也会让上游作业号更大的
385		// 依赖链在单趟级联扫描中漏掉失败传播）。
386		sort.Slice(jobs, func(a, b int) bool {
387			return jobs[a].id < jobs[b].id
388		})
389		// 第二趟：按作业号升序单趟处理依赖失效。直接上游在提交时必须已存在，
390		// 上游作业号必然更小，因此每个作业被处理时其全部直接上游都已是本次恢复
391		// 确定的最终状态——上游被改判失败时携带的根因作业号可直接沿链条继承，
392		// 不会在每经过一个已归档的中间作业时重新起算。
393		//
394		// 两类作业遵守同一项归因规则（与正常运行中的依赖失败一致）：失败原因
395		// 指出当前作业的直接上游，BlockerID 沿链条保留最初使结果不可用的根因；
396		// 只有本作业自身归档有误（上游全部有效、仅保存的追加输入不符）时
397		// BlockerID 才保持 0。
398		//   - 带依赖的成功记录：追加部分与上游恢复后的结果逐项核对；
399		//   - 排队记录：先检查依赖列表自身是否合法——重复引用同一作业号，或
400		//     引用作业号不小于自己的作业（自己或后来作业），都属本作业自身有误，
401		//     BlockerID 为 0，立即失败且重复检查优先（保留现有重复失败说明）；
402		//     再按保存的依赖顺序选取最靠前的不可用上游（已失败/取消，或记录
403		//     缺失），立即级联失败，不再等待。
404		//
405		// 依赖列表自身不合法属于记录自身问题，先于一切上游可用性判断：即使被引用
406		// 的上游仍在排队或确实存在且成功，不合法记录也要立即失败；而等待该记录
407		// 结果的下游则按既有规则把它当作失败上游级联，根因就是这份记录自身。
408		byID := make(map[uint64]*storedJob, len(jobs))
409		for _, j := range jobs {
410			byID[j.id] = j
411		}
412		for _, j := range jobs {
413			if len(j.dependencies) == 0 {
414				continue
415			}
416			switch j.status {
417			case StatusSucceeded:
418				// 第一趟：按保存的依赖顺序找最靠前的不可用上游（记录缺失或恢复后
419				// 未保持带完整归档的成功状态）。
420				directID, dep, unavailable := pickBlockingUpstream(j, byID, restoredArchiveUpstreamBlocked)
421				if unavailable {
422					// 因直接上游结果失效而失败：根因沿该上游已有的阻断信息保留，
423					// 直接上游记录缺失时以缺失的作业号本身作为根因。
424					root := blockerRoot(dep, directID)
425					failRestoredJob(dir, j, blockedFailureReason(restoredArchiveHead(directID), dep, directID, root), root)
426					continue
427				}
428				// 第二趟：直接上游全部存在且有效，只是本作业保存的追加输入与上游
429				// 总和按位置对不上——属于本作业自身归档有误，不把有效上游判成
430				// 失败或归因给它，BlockerID 保持 0。
431				if _, detail, mismatch := firstAppendedMismatch(j, byID); mismatch {
432					failRestoredJob(dir, j, detail, 0)
433				}
434			case StatusQueued:
435				// 排队记录的依赖列表同样不能重复引用同一作业号：这属于本作业记录
436				// 自身有误，在选取不可用上游之前直接判失败——不能开始计算，也不能
437				// 把同一上游总和追加两次后继续。BlockerID 保持 0，不把被重复引用
438				// 且原本有效的上游改成失败。
439				if dupID, dup := duplicateDependency(j); dup {
440					failRestoredJob(dir, j, duplicateDependencyReason(dupID), 0)
441					continue
442				}
443				// 依赖先后关系同样是记录自身问题：直接上游作业号必须严格小于本作业号，
444				// 引用自己或后来作业即使被引用者存在且成功也不能接受，不能开始计算或
445				// 继续等待。排在重复检查之后，已因重复依赖判失败的记录保留现有说明。
446				if badID, bad := firstIllegalOrderingDependency(j); bad {
447					failRestoredJob(dir, j, illegalOrderingDependencyReason(badID, j.id), 0)
448					continue
449				}
450				// 按保存的依赖顺序选取最靠前的不可用上游；其他上游作业号更小
451				// 或失败原因不同都不能改变这个选择。
452				directID, direct, blocked := pickBlockingUpstream(j, byID, restoredQueuedUpstreamBlocked)
453				if !blocked {
454					continue // 上游仍在排队等情况：继续等待，不挡住其他作业。
455				}
456				root := blockerRoot(direct, directID)
457				if direct == nil {
458					// 直接上游的记录在归档目录中缺失，其结果不可能再变为可用：
459					// 以缺失的作业号作为根因，并明确说明结果无法使用。
460					failRestoredJob(dir, j, blockedFailureReason(restoredMissingHead(directID), nil, directID, root), root)
461					continue
462				}
463				failRestoredJob(dir, j, blockedFailureReason(runtimeBlockedHead(direct), direct, directID, root), root)
464			}
465		}
466		return jobs, maxID, nil
467	}
468	
469	// failRestoredJob 收拢重新打开归档时把恢复出的作业改判为失败的统一处理，
470	// 供五类恢复失败共用（调用顺序即各类判定的既有先后）：
471	//   - 上次关闭时仍在运行的作业：计算被中断（第一趟记录扫描）；
472	//   - 原标为成功、但归档完整性、依赖列表唯一性或先后关系、实际输入对应
473	//     关系或数值结果不符规则的作业：本作业自身归档校验失败（第一趟记录
474	//     扫描，BlockerID 恒 0；唯一性检查先于先后关系检查）；
475	//   - 排队记录的依赖列表重复引用同一作业号：本作业记录自身有误（第二趟升序
476	//     扫描，BlockerID 恒 0，先于上游可用性判断）；
477	//   - 排队记录引用作业号不小于自己的作业（自己/后来作业）：本作业记录自身
478	//     有误（第二趟升序扫描，BlockerID 恒 0，在重复检查之后、上游可用性
479	//     判断之前）；
480	//   - 被不可用直接上游阻断的作业：成功记录复核与排队记录复查（第二趟升序扫描），
481	//     BlockerID 由调用方按 blocker.go 的归因规则给出。
482	//
483	// 处理内容与各处原先内联的步骤完全一致：置失败状态、失败原因与阻断根因；
484	// 已经有完成时间的记录保留该时间，只有没有完成时间的才补上当前时间；
485	// 清除成功归档与实际参与计算的输入，使按作业号读取与按提交人列举都不再返回
486	// 成功归档或实际输入；作业号、提交人、请求号、原始整数次序、种子、依赖次序
487	// 与已有开始时间均不在此改动。归档可正常写入时，变化经同一条记录的一次
488	// 原子替换写回磁盘，而不只停留在内存查询结果中；写入失败维持既有尽力而为
489	// 语义（不因恢复阶段的一次落盘失败让整个归档无法打开）。
490	func failRestoredJob(dir string, j *storedJob, reason string, blocker uint64) {
491		j.status = StatusFailed
492		j.failureReason = reason
493		j.blockerID = blocker
494		if j.finishedAt.IsZero() {
495			j.finishedAt = time.Now().UTC()
496		}
497		j.effectiveValues = nil
498		j.archive = nil
499		if data, err := encodeRecord(j); err == nil {
500			_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
501		}
502	}
503	
504	// archiveIntact 复算成功归档的全部确定性字段，任何不一致都视为不可用。
505	func archiveIntact(j *storedJob) bool {
506		a := j.archive
507		if a == nil {
508			return false
509		}
510		// 归档中的原始参数必须与记录顶层字段一致。
511		wantHasDependency, wantDependencyID := legacyDependencyFields(j.dependencies)
512		if a.JobID != j.id || a.Submitter != j.submitter || a.RequestID != j.requestID ||
513			a.Seed != j.seed || a.HasDependency != wantHasDependency {
514			return false
515		}
516		if a.HasDependency && a.DependencyID != wantDependencyID {
517			return false
518		}
519		// 依赖列表（内容与次序）必须一致。旧格式归档没有 dependencies 字段，
520		// 由单依赖字段推导后再比较，与记录恢复、提交内容比较共用同一换算。
521		aDeps := normalizeDependencies(a.HasDependency, a.DependencyID, a.Dependencies)
522		if len(aDeps) != len(j.dependencies) {
523			return false
524		}
525		for i := range j.dependencies {
526			if aDeps[i] != j.dependencies[i] {
527				return false
528			}
529		}
530		if len(a.Values) != len(j.values) {
531			return false
532		}
533		for i := range j.values {
534			if a.Values[i] != j.values[i] {
535				return false
536			}
537		}
538		if len(j.effectiveValues) == 0 || len(a.EffectiveValues) != len(j.effectiveValues) {
539			return false
540		}
541		for i := range j.effectiveValues {
542			if j.effectiveValues[i] != a.EffectiveValues[i] {
543				return false
544			}
545		}
546		if a.InputsDigest != inputsDigestHex(j.effectiveValues, j.seed) {
547			return false
548		}
549		if a.ResultDigest != resultDigestHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
550			return false
551		}
552		if a.Log != buildLog(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
553			return false
554		}
555		if a.Checksum != checksumHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares, a.Log, a.ResultDigest) {
556			return false
557		}
558		return true
559	}
560	
561	// archiveResultsValid 按既有计算规则对归档保存的实际输入（effectiveValues，
562	// 已含按顺序追加的上游总和，不再追加）复算总和与平方和，归档中的数值结果
563	// 必须与复算结果完全一致。完整性检查只验证日志、摘要与校验值和所写数字
564	// 自洽，无法识别“数字本身写错但全套字段一致”的记录，因此这里以计算规则
565	// 为准。实际输入按规则会造成 int64 溢出时 ok 为 false，任何数值结果
566	// （包括回绕后的值）都不能作为有效成功结果保留。
567	//
568	// 调用前须已通过 archiveIntact（保证 archive 非空且有效输入非空）。
569	func archiveResultsValid(j *storedJob) bool {
570		a := j.archive
571		sum, sumSquares, _, ok := computeResult(j.effectiveValues, j.seed, nil)
572		if !ok {
573			return false
574		}
575		return a.Sum == sum && a.SumOfSquares == sumSquares
576	}
577	
578	// effectiveInputsCorrespond 校验成功记录中实际参与计算的输入与原始提交
579	// 参数、直接依赖数量之间的对应关系：
580	//   - 原始序列必须非空；
581	//   - 原始序列逐项、按原次序完整出现在实际输入的开头——负数、零与重复
582	//     整数一律按位置判断，不比较总和或平方和，也不忽略次序；
583	//   - 实际输入总长度必须恰好等于原始序列长度加直接依赖数量。无依赖时两份
584	//     序列必须完全相同；有单个或多个依赖时，原始部分之后只能保留每个直接
585	//     上游各占一个位置的追加部分，不能借依赖之名替换、截短原始部分，也不
586	//     能多出未记录的输入。
587	//
588	// 该规则防止把另一份输入的自洽结果挂在原始参数下：例如原始参数为 [2,-3]
589	// 而实际输入被换成 [-3,2] 时，总和与平方和不变，摘要、日志与校验值又只
590	// 绑定实际输入，全套字段仍会自洽，只有按位置比对原始参数并核对追加数量
591	// 才能识别。旧的单依赖记录恢复后依赖列表恰含一个作业号，按同一含义判断。
592	//
593	// 调用前须已通过 archiveIntact（保证 archive 非空、实际输入非空且归档内
594	// 副本与顶层一致）。
595	func effectiveInputsCorrespond(j *storedJob) bool {
596		n := len(j.values)
597		if n == 0 {
598			return false
599		}
600		if len(j.effectiveValues) != n+len(j.dependencies) {
601			return false
602		}
603		for i := 0; i < n; i++ {
604			if j.effectiveValues[i] != j.values[i] {
605				return false
606			}
607		}
608		return true
609	}
610

