144	// 再沿该上游已有的阻断信息确定根因；其他上游作业号更小或失败原因不同都不能
145	// 改变这个选择。
146	func TestReopenMultiDependencyPicksEarliestUnavailableAndKeepsItsRoot(t *testing.T) {
147		dir := t.TempDir()
148		s, err := Open(dir)
149		if err != nil {
150			t.Fatal(err)
151		}
152		// root → bad：bad 已成功归档但重开时因 root 失效而改判，blocker=root。
153		root := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "root", Values: []int64{2, -3}})
154		waitStatus(t, s, root.ID, StatusSucceeded)
155		bad := mustSubmit(t, s, SubmitRequest{
156			Submitter: "a", RequestID: "bad", Values: []int64{5},
157			Dependencies: []uint64{root.ID},
158		})
159		waitStatus(t, s, bad.ID, StatusSucceeded)
