161		other := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "other", Values: []int64{7}})
162		waitStatus(t, s, other.ID, StatusSucceeded)
163		// down 依赖顺序为 [other, bad]：最靠前的不可用上游是 bad（other 仍有效），
164		// 根因须沿 bad 已有的阻断信息保留为 root，而不是 bad 本身。
165		down := mustSubmit(t, s, SubmitRequest{
166			Submitter: "a", RequestID: "down", Values: []int64{1},
167			Dependencies: []uint64{other.ID, bad.ID},
168		})
169		waitStatus(t, s, down.ID, StatusSucceeded)
170		// child 排队等待 down，进一步验证根因跨已归档/排队边界传播。
171		if err := s.Close(); err != nil {
172			t.Fatal(err)
173		}
174	
175		rewriteRecordNumbers(t, dir, root.ID, 8, 13)
176		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
177		writeSyntheticRecord(t, dir, &storedJob{
178			id: down.ID + 100, submitter: "a", requestID: "child",
179			values: []int64{2}, dependencies: []uint64{down.ID},
180			queuedAt: base,
181			status:   StatusQueued,
182		})
183	
184		s2, err := Open(dir)
185		if err != nil {
186			t.Fatal(err)
187		}
188		defer s2.Close()
189	
190		gOther, _ := s2.Get(other.ID)
191		if gOther.Status != StatusSucceeded {
192			t.Fatalf("有效上游 other 不应被改判: %s", gOther.Status)
193		}
194		gBad, _ := s2.Get(bad.ID)
195		if gBad.Status != StatusFailed || gBad.BlockerID != root.ID {
196			t.Fatalf("bad blocker=%d want root %d", gBad.BlockerID, root.ID)
197		}
198		gDown, _ := s2.Get(down.ID)
199		if gDown.Status != StatusFailed || gDown.BlockerID != root.ID {
200			t.Fatalf("down 应选列表中最靠前的不可用上游 bad 并保留根因 root: blocker=%d want %d",
201				gDown.BlockerID, root.ID)
202		}
203		if !strings.Contains(gDown.FailureReason, "直接上游作业 "+itoa(bad.ID)) {
204			t.Fatalf("down 原因须指出直接上游 bad %d: %q", bad.ID, gDown.FailureReason)
205		}
206		gChild := waitStatus(t, s2, down.ID+100, StatusFailed)
207		if gChild.BlockerID != root.ID {
208			t.Fatalf("child blocker=%d want root %d", gChild.BlockerID, root.ID)
209		}
210		if !strings.Contains(gChild.FailureReason, "直接上游作业 "+itoa(down.ID)) ||
211			!strings.Contains(gChild.FailureReason, "阻断根因为作业 "+itoa(root.ID)) {
212			t.Fatalf("child 须指出直接上游 down 与根因 root: %q", gChild.FailureReason)
213		}
214	}
215	
216	// 多依赖记录中既保存了错误的追加值（对应位置上游仍有效）、又有更靠后的
217	// 上游不可用时：归因仍按“最靠前的不可用上游”确定根因，有效上游处的追加
218	// 值错误属于本作业归档问题，但不改变对不可用上游及其根因的选择。
219	func TestReopenUnavailableUpstreamOutranksValidPositionMismatch(t *testing.T) {
