230			Submitter: "a", RequestID: "bad", Values: []int64{5},
231			Dependencies: []uint64{root.ID},
232		})
233		waitStatus(t, s, bad.ID, StatusSucceeded)
234		// down 的依赖顺序 [good, bad]：真实追加应为 [10, badSum]。
235		down := mustSubmit(t, s, SubmitRequest{
236			Submitter: "a", RequestID: "down", Values: []int64{1},
237			Dependencies: []uint64{good.ID, bad.ID},
238		})
