270	
271	// 已成功归档的作业，其直接上游记录缺失时该作业以缺失的作业号为根因，并明确
272	// 说明结果无法使用；排队等待它的下游继续把同一缺失作业号作为根因。
273	func TestReopenMissingUpstreamRecordBecomesRoot(t *testing.T) {
