func failArchiveWrite(s *Store, id uint64) {
	s.persistFault = func(j *storedJob) error {
		if j.id == id && j.status == StatusSucceeded && j.archive != nil {
			return errors.New("numeric(测试故障): 模拟结果归档写入失败")
		}
