	indep := mustSubmit(t, s, SubmitRequest{
		Submitter: "a", RequestID: "indep", Values: []int64{5},
	})

	// 放行后上游计算成功，但归档保存失败；此后不做任何提交/取消操作，
	// 仅靠 Get 轮询（只读，不触发级联）就应观察到失败沿链条传播。
	release(up.ID)

